mapper.select:
SELECT ul.*
FROM sr_user_lightcone ul
INNER JOIN sr_lightcone lc ON ul.lightcone_id = lc.id

     AND ul.user_id = #{userId}
     AND ul.lightcone_id = #{lightConeId}
     AND ul.level = #{level}
     AND ul.superimposition = #{superimposition}

ORDER BY lc.sort_order desc

select ulc.id, ulc.user_id, ulc.lightcone_id, ulc.level, ulc.superimposition,
       ulc.create_by, ulc.create_time, ulc.update_by, ulc.update_time, ulc.remark,
       lc.lightcone_name, lc.image, lc.star_level, lc.path
from sr_user_lightcone ulc
left join sr_lightcone lc on ulc.lightcone_id = lc.id
where ulc.user_id = #{userId}

    and lc.path = #{path}


    and lc.star_level = #{starLevel}


    and lc.lightcone_name like concat('%', #{lightConeName}, '%')

order by lc.sort_order desc, ulc.level desc, ulc.superimposition desc

mapper.update:
update sr_user_lightcone
user_id = #{userId}, lightcone_id = #{lightConeId}, level = #{level}, superimposition = #{superimposition}, create_by = #{createBy}, create_time = #{createTime}, update_by = #{updateBy}, update_time = #{updateTime}, remark = #{remark},
where id = #{id}
